-- Red Solar Viva · STICKERS · 10 emblemas NUEVOS del paquete "Red Solar Viva" (2026-07-13)
-- =====================================================================
-- Aplicar: Supabase Dashboard -> SQL Editor -> New Query -> Run.
-- Requiere 20260625e_dm_stickers.sql + 20260625f_default_sticker_pack.sql.
--
-- 10 stickers SVG propios que amplian el stack de la mensajeria con zonas
-- expresivas nuevas (sort 6-15): Amanecer (buenos dias) - Luna de cristal
-- (buenas noches) - Sin energia (bateria drenada) - Alta frecuencia (rayo) -
-- Meditando - En sintonia (dos nodos conectados) - Sellado (palomita
-- hexagonal) - Escaneando (radar) - Racha viva (flama) - Pregunta de
-- cristal. Mismo formato del seed original: data:image/svg+xml;base64 en
-- image_url (sin R2, el <img> los renderiza nativo). Idempotente: solo
-- inserta si el paquete sigue con sus 5 stickers originales.

DO $$
DECLARE
    v_pack bigint;
    v_count int;
BEGIN
    SELECT id INTO v_pack FROM public.sticker_packs WHERE name = 'Red Solar Viva' LIMIT 1;
    IF v_pack IS NULL THEN
        RAISE NOTICE 'Paquete "Red Solar Viva" no existe -- corre antes 20260625f.';
        RETURN;
    END IF;
    SELECT count(*) INTO v_count FROM public.stickers WHERE pack_id = v_pack;
    IF v_count >= 6 THEN
        RAISE NOTICE 'Los stickers nuevos ya estaban insertados (count=%).', v_count;
        RETURN;
    END IF;

    INSERT INTO public.stickers (pack_id, image_url, is_animated, sort_order) VALUES
      (v_pack, 'data:image/svg+xml;base64,' || replace(encode(convert_to($svg6$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120"><defs><radialGradient id="a" cx="50%" cy="62%" r="55%"><stop offset="0%" stop-color="#FFF7E0"/><stop offset="52%" stop-color="#F5D98C"/><stop offset="100%" stop-color="#D4A843"/></radialGradient><radialGradient id="g" cx="50%" cy="60%" r="58%"><stop offset="0%" stop-color="#F5D98C" stop-opacity="0.5"/><stop offset="100%" stop-color="#F5D98C" stop-opacity="0"/></radialGradient><linearGradient id="hz" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stop-color="#36C9E0" stop-opacity="0"/><stop offset="50%" stop-color="#36C9E0"/><stop offset="100%" stop-color="#36C9E0" stop-opacity="0"/></linearGradient></defs><circle cx="60" cy="66" r="52" fill="url(#g)"/><path d="M32 74 A28 28 0 0 1 88 74 Z" fill="url(#a)"/><path d="M32 74 A28 28 0 0 1 88 74" fill="none" stroke="#FFF7E0" stroke-opacity="0.65" stroke-width="1.6"/><g stroke="#F5D98C" stroke-width="4" stroke-linecap="round"><line x1="60" y1="34" x2="60" y2="22"/><line x1="38" y1="43" x2="30" y2="34"/><line x1="82" y1="43" x2="90" y2="34"/><line x1="27" y1="62" x2="16" y2="59"/><line x1="93" y1="62" x2="104" y2="59"/></g><rect x="14" y="73" width="92" height="3" rx="1.5" fill="url(#hz)"/><rect x="26" y="82" width="68" height="2" rx="1" fill="url(#hz)" opacity="0.5"/><circle cx="88" cy="28" r="2.2" fill="#EAFBFF"/><circle cx="30" cy="52" r="1.7" fill="#FFF7E0"/></svg>$svg6$, 'UTF8'), 'base64'), E'\n', ''), false, 6),
